<?php

declare(strict_types=1);

namespace TreeshaInfotech\Vapi\Builders;

use Vapi\Calls\Requests\UpdateCallDto;

/**
 * Fluent builder for UpdateCallDto.
 *
 * Generated by `composer build:builders`. Do not edit; regenerate after
 * upgrading vapi/vapi.
 */
final class UpdateCallBuilder
{
    private ?string $name = null;

    public static function make(): self
    {
        return new self;
    }

    public function name(string $name): self
    {
        $this->name = $name;

        return $this;
    }

    public function build(): UpdateCallDto
    {
        $values = array_filter([
            'name' => $this->name,
        ], static fn (mixed $value): bool => $value !== null);

        return new UpdateCallDto($values);
    }
}
